select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:1' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987125002 and t.language='nl')='{"text":"Advocaat Victor Carl probeert een nieuw proces te krijgen voor een man die voor de moord op zijn vrouw is veroordeeld. Hij komt daarbij niet alleen tegenover politie en aanklager te staan, maar krijgt ook te maken met Bob, een opvallend behulpzame bemoeial. Dankzij hem lijkt Victors eigen leven op verschillende punten beter te worden. Wanneer er een verband blijkt tussen Bob en de vermoorde vrouw, wordt die hulp minder geruststellend. De zaak dwingt Victor opnieuw te beoordelen wat achter de goede bedoelingen van anderen kan schuilgaan.","work_id":987125002,"evidence":[{"note":"ExactDutchA.W.Bruna2007paperback9789022991411/FallsTheShadow2005 with translatorJanSmit. FrontWilliamLashner/Deverliezers matches exact source; do not substitute anotherVictorCarlbook or confuse publicationyear2005original with2007translation.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p297930710"],"reference":"work:6319","checked_at":"2026-11-02T22:27:17.469Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-034.json","sources":["https://www.bol.com/nl/nl/p/de-verliezers/1001004002605001/","https://knihobot.cz/g/9701014","https://openlibrary.org/works/OL2952400W","https://data.bibliotheken.nl/id/nbt/p297930710"]},{"type":"cover_front_review","sha256":"f53d979e01d6501ec2d606f8728de437e957e4dff5011af3eeb73e0d09bf48e3","cover_id":13010512,"reference":"cover-semantic-review-011.json","limitation":"William Lashner; De verliezers; classical colonnade and eye; thriller heading."}],"language":"nl","provenance":"original_source