id":987325001}'::jsonb as exact union all select 'catalog_work_descriptions:3' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987125001 and t.language='nl')='{"text":"Arthur Japin brengt persoonlijke reisverhalen bijeen die samenhangen met de voorbereiding van zijn werk. Sommige tochten voeren naar Patagonië, Kenia of afgelegen delen van de Verenigde Staten, andere blijven dichter bij huis. Ervaringen uit dagboeken en eerder verspreide stukken staan naast teksten die nog niet waren verschenen. De bundel laat zien hoe waarnemingen onderweg verbonden kunnen raken met fictie. Niet alleen de bestemming, maar vooral zijn eigen betrokkenheid en de band met het latere schrijven vormen de samenhang tussen de verhalen.","work_id":987125001,"evidence":[{"note":"ExactDutchMagonia2016hardcover9789492241078 travelpieces, not a novel or interchangeableJapinmemoir. DutchauthorArthurValentijnJapin aliasmatchesNTA; 128vs159pagevalues are printing/catalogue disagreements, no invented paginationcorrection.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p394220579"],"reference":"work:3247","checked_at":"2026-11-02T22:27:17.469Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-035.json","sources":["https://www.standaardboekhandel.be/p/goed-volk-9789492241078","https://www.boekwinkeltjes.nl/b/244577886/Goed-volk/","https://openlibrary.org/works/OL34828070W","https://data.bibliotheken.nl/id/nbt/p394220579"]},{"type":"cover_front_review","sha256":"067cf279946b1e119ae9307e13bc4ff002f039771828afc0f1f83e1536684e24","cover_id":13602626,"reference":"cover-semantic-review-011.json","limitation":"Arthur Japin; Goed volk; Reisverhalen; orange/yellow illustrated figures."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.standaardboekhandel.be/p/goed-volk-9789492241078","reviewed_at":"2026-11-02T22:27:17.469+00:00","source